// QA Sprint 0 shell check (scratch, not committed). Usage: node shell-check.mjs <pkgDir> <url> <outDir>
import { createRequire } from 'node:module';
import path from 'node:path';

const [pkgDir, url, outDir] = process.argv.slice(2);
const require = createRequire(path.join(pkgDir, 'package.json'));
const { chromium } = require('@playwright/test');
const { AxeBuilder } = require('@axe-core/playwright');

// Expected text retyped independently from docs/user-stories.md (not imported from messages.ts).
const M = {
  1: 'Enter marks earned and total marks possible to see the score.',
  25: 'Next learner',
  30: 'Quiz score and pass-mark calculator',
  31: 'Quiz score',
  32: 'Check a quiz result',
  33: 'A score at or above the pass mark is a pass.',
  34: 'Marks earned',
  35: 'Total marks possible',
  36: 'Pass mark',
  37: ' (percent)',
  38: '%',
  39: 'Score',
  40: 'or press Esc',
};

const results = [];
const check = (name, ok, detail = '') => {
  results.push({ name, ok: Boolean(ok), detail });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`);
};

const browser = await chromium.launch();
const consoleLog = [];
const external = [];

async function newPage(opts = {}) {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, ...opts });
  const page = await ctx.newPage();
  page.on('console', (m) => consoleLog.push(`[${opts.colorScheme ?? 'light'}] console.${m.type()}: ${m.text()}`));
  page.on('pageerror', (e) => consoleLog.push(`pageerror: ${e.message}`));
  page.on('requestfailed', (r) => consoleLog.push(`requestfailed: ${r.url()}`));
  page.on('request', (r) => { if (!r.url().startsWith('http://127.0.0.1:4173')) external.push(r.url()); });
  await page.goto(url, { waitUntil: 'networkidle' });
  return { ctx, page };
}

{
